def Convertir_limitations(apps, schema_editor):
    """ Convertit l'ancien champ limitations (ex : '2EVTSEMAINE') en règles de limitation """
    CategorieEvenement = apps.get_model("core", "CategorieEvenement")
    LimitationCategorieEvenement = apps.get_model("core", "LimitationCategorieEvenement")
    for categorie in CategorieEvenement.objects.exclude(limitations__isnull=True).exclude(limitations=""):
        code = categorie.limitations
        periode = "SEMAINE" if "SEMAINE" in code else "JOUR" if "JOUR" in code else None
        nbre_max = int(code.split("EVT")[0]) if code.split("EVT")[0].isdigit() else None
        if periode and nbre_max:
            LimitationCategorieEvenement.objects.create(categorie=categorie, nbre_max=nbre_max, periode=periode)


def Restaurer_limitations(apps, schema_editor):
    """ Retour arrière : reprend la première règle jour/semaine de chaque catégorie (si compatible avec les anciens choix) """
    CategorieEvenement = apps.get_model("core", "CategorieEvenement")
    LimitationCategorieEvenement = apps.get_model("core", "LimitationCategorieEvenement")
    for regle in LimitationCategorieEvenement.objects.filter(periode__in=("JOUR", "SEMAINE")).order_by("pk"):
        code = "%dEVT%s" % (regle.nbre_max, regle.periode)
        if code in ("1EVTJOUR", "2EVTJOUR", "3EVTJOUR", "1EVTSEMAINE", "2EVTSEMAINE", "3EVTSEMAINE", "4EVTSEMAINE"):
            CategorieEvenement.objects.filter(pk=regle.categorie_id, limitations__isnull=True).update(limitations=code)


